// Validasi field wajib dari order yang masuk lewat webhook.
// Hasil: { valid: true/false, errors: [...], order: {...data asli...} }
const WAJIB = ['channel', 'no_pesanan', 'sku', 'qty', 'nama_pembeli', 'no_hp'];
const CHANNEL_DIKENAL = ['shopee', 'tiktok', 'whatsapp'];

return $input.all().map((item) => {
  const body = item.json.body || {};
  const kosong = (v) => v === undefined || v === null || String(v).trim() === '';
  const errors = [];

  for (const field of WAJIB) {
    if (kosong(body[field])) errors.push(`Field '${field}' wajib diisi`);
  }
  if (!kosong(body.channel) && !CHANNEL_DIKENAL.includes(String(body.channel).trim().toLowerCase())) {
    errors.push(`Field 'channel' harus salah satu dari: ${CHANNEL_DIKENAL.join(', ')}`);
  }
  if (!kosong(body.qty)) {
    const qty = Number(body.qty);
    if (!Number.isInteger(qty) || qty <= 0) errors.push("Field 'qty' harus angka bulat lebih dari 0");
  }
  if (!kosong(body.sku) && !/^GLW-[A-Z]{3}-\d{3}$/.test(String(body.sku).trim().toUpperCase())) {
    errors.push("Field 'sku' harus berformat GLW-XXX-000 (contoh: GLW-SRM-001)");
  }
  if (!kosong(body.no_hp)) {
    const digit = String(body.no_hp).replace(/\D/g, '');
    if (digit.length < 9 || digit.length > 15) errors.push("Field 'no_hp' harus berisi 9-15 digit angka");
  }

  return { json: { valid: errors.length === 0, errors, order: body } };
});

// Rapikan data order: nomor HP -> 628xxx, SKU huruf besar, nama Huruf Awal Kapital.
// Aturan sama dengan scripts/clean_merge.py supaya hasilnya konsisten.
return $input.all().map((item) => {
  const o = item.json.order;

  let hp = String(o.no_hp).replace(/\D/g, '');      // buang spasi, strip, +, ( )
  if (hp.startsWith('0')) hp = '62' + hp.slice(1);  // 0812... -> 62812...
  else if (hp.startsWith('8')) hp = '62' + hp;      // 812...  -> 62812...
  const hpValid = hp.startsWith('628') && hp.length >= 11 && hp.length <= 14;

  const nama = String(o.nama_pembeli)
    .trim()
    .replace(/\s+/g, ' ')
    .replace(/^(kak|ka|kk)\s+/i, '')
    .toLowerCase()
    .replace(/(^|\s)\S/g, (c) => c.toUpperCase());

  return {
    json: {
      status: hpValid ? 'diterima' : 'perlu_cek',
      pesan: hpValid
        ? 'Order diterima dan siap diproses'
        : 'Order diterima, tapi nomor HP bukan nomor Indonesia (628...). Mohon cek manual.',
      order: {
        channel: String(o.channel).trim().toLowerCase(),
        no_pesanan: String(o.no_pesanan).trim(),
        sku: String(o.sku).trim().toUpperCase(),
        qty: Number(o.qty),
        nama_pembeli: nama,
        no_hp_asli: o.no_hp,
        no_hp_normal: hp,
      },
      diterima_pada: new Date().toISOString(),
    },
  };
});
